int lengthOfLongestSubstring(const string &s) {
    unordered_map<char,int> last;
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        char ch = s[right];
        if (last.count(ch) && last[ch] >= left) left = last[ch] + 1;
        last[ch] = right;
        best = max(best, right - left + 1);
    }
    return best;
}

